interface Iterator { next(); hasNext(): boolean; }
class ArrayIterator implements Iterator {
  private i = 0;
  constructor(private colecao) {}
  hasNext() { return this.i < this.colecao.length; }
  next() { return this.colecao[this.i++]; }
}

